  "service_id" TEXT NOT NULL,
  "quantity" BIGINT DEFAULT 1 NOT NULL,
  "total_price" NUMERIC(14,2) DEFAULT 0 NOT NULL,
  "status" TEXT DEFAULT 'pending' NOT NULL,
  "notes" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "payment_id" TEXT,
  "payment_status" TEXT DEFAULT 'none',
  "service_date" DATE,
  PRIMARY KEY ("id"),
  CHECK (status IN ('pending', 'confirmed', 'cancelled')),
  CHECK (payment_status IN ('none', 'pending', 'paid', 'failed', 'refunded'))
);

CREATE TABLE "service_time_slots" (
  "id" TEXT DEFAULT encode(gen_random_bytes(16), 'hex') NOT NULL,
  "service_id" TEXT NOT NULL,
  "date" DATE NOT NULL,
  "start_time" TEXT NOT NULL,
  "end_time" TEXT NOT NULL,
  "max_capacity" BIGINT DEFAULT 1 NOT NULL,
  "booked_count" BIGINT DEFAULT 0 NOT NULL,
  "is_available" BOOLEAN DEFAULT true NOT NULL,
  "reservation_id" TEXT,
  "booking_session_id" TEXT,
  "notes" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("service_id", "date", "start_time")
);

CREATE TABLE "sessions" (
  "id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "expires_at" TIMESTAMPTZ NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "finance_unlocked_until" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE "settings" (
  "key" TEXT NOT NULL,
  "value" TEXT,
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("key")
);

CREATE TABLE "site_incoming_leads" (
  "id" TEXT DEFAULT encode(gen_random_bytes(16), 'hex') NOT NULL,
  "site_id" TEXT NOT NULL,
  "full_name" TEXT,
  "email" TEXT,
  "phone" TEXT,
  "message" TEXT,
  "status" TEXT DEFAULT 'new' NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  PRIMARY KEY ("id"),
  CHECK (status IN ('new', 'read', 'archived'))
);

CREATE TABLE "site_listings" (
  "id" TEXT DEFAULT encode(gen_random_bytes(16), 'hex') NOT NULL,
  "site_id" TEXT NOT NULL,
  "unit_id" TEXT,
  "unit_type_id" TEXT,
  "price_override" NUMERIC(14,2),
  "rules_override" TEXT,
  "has_rules_override" BOOLEAN DEFAULT false NOT NULL,
  "max_inventory" BIGINT,
  "external_url" TEXT,
  "sort_order" BIGINT DEFAULT 0 NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "photos" TEXT,
  "thank_you_url" TEXT,
  "default_lang" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE "site_rate_plans" (
  "id" TEXT DEFAULT encode(gen_random_bytes(16), 'hex') NOT NULL,
  "site_id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "is_default" BOOLEAN DEFAULT false NOT NULL,
  "cancellation_policy" TEXT DEFAULT 'non_refundable' NOT NULL,
  "payment_schedule" TEXT DEFAULT '[{"percent": 100, "trigger": "on_booking"}]' NOT NULL,
  "meals_included" TEXT DEFAULT '[]' NOT NULL,
  "min_days_before_checkin" BIGINT DEFAULT 0 NOT NULL,
  "same_day_cutoff_hour" BIGINT,
  "min_stay" BIGINT DEFAULT 1 NOT NULL,
  "max_stay" BIGINT DEFAULT 999 NOT NULL,
  "pricing_mode" TEXT DEFAULT 'independent' NOT NULL,
  "applied_listings" JSONB DEFAULT '[]'::jsonb NOT NULL,
  "is_active" BOOLEAN DEFAULT true NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "updated_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "pricing_modifier_percent" DOUBLE PRECISION,
  "pricing_modifier_type" TEXT DEFAULT 'less',
  "derived_from_plan_id" TEXT,
  "valid_weekdays" TEXT,
  PRIMARY KEY ("id"),
  CHECK (cancellation_policy IN ('non_refundable', 'full_refund', 'flexible')),
  CHECK (pricing_mode IN ('independent', 'dependent'))
);

CREATE TABLE "site_services" (
  "id" TEXT DEFAULT encode(gen_random_bytes(16), 'hex') NOT NULL,
  "site_id" TEXT NOT NULL,
  "service_id" TEXT NOT NULL,
  "is_enabled" BOOLEAN DEFAULT true NOT NULL,
  "price_override" NUMERIC(14,2),
  "sort_order" BIGINT DEFAULT 0 NOT NULL,
