CREATE TABLE "units" (
  "id" TEXT DEFAULT encode(gen_random_bytes(16), 'hex') NOT NULL,
  "unit_type_id" TEXT NOT NULL,
  "property_id" TEXT NOT NULL,
  "category_id" TEXT NOT NULL,
  "building_id" TEXT,
  "name" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "floor" BIGINT,
  "zone" TEXT,
  "beds" BIGINT DEFAULT 2 NOT NULL,
  "room_status" TEXT DEFAULT 'available' NOT NULL,
  "cleaning_status" TEXT DEFAULT 'clean' NOT NULL,
  "notes" TEXT,
  "sort_order" BIGINT DEFAULT 0 NOT NULL,
  "is_active" BOOLEAN DEFAULT true NOT NULL,
  "is_pool" BOOLEAN DEFAULT false NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "updated_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "lock_code" TEXT,
  "entry_photo_url" TEXT,
  PRIMARY KEY ("id"),
  UNIQUE ("property_id", "code"),
  CHECK (room_status IN ('available', 'occupied', 'maintenance', 'blocked')),
  CHECK (cleaning_status IN ('clean', 'dirty', 'in_progress'))
);

