CREATE TABLE "widget_price_list" (
  "id" TEXT DEFAULT encode(gen_random_bytes(16), 'hex') NOT NULL,
  "category" TEXT NOT NULL,
  "item_code" TEXT NOT NULL,
  "item_name" TEXT NOT NULL,
  "rate_standard" DOUBLE PRECISION DEFAULT 0 NOT NULL,
  "rate_holiday" DOUBLE PRECISION,
  "rate_side_season" DOUBLE PRECISION,
