  "notes" TEXT,
  "sort_order" BIGINT DEFAULT 0,
  "is_active" BOOLEAN DEFAULT true,
  "updated_at" TIMESTAMPTZ DEFAULT now() NOT NULL,
  "organization_id" TEXT,
  PRIMARY KEY ("id"),
  UNIQUE ("organization_id", "item_code"),
  CHECK (category IN ('glamping', 'buildings', 'camping'))
);

