-- ── Row-level security ──────────────────────────────────────────────────
--
-- The application connects as a role that is NOT the table owner and NOT
-- superuser, so these policies actually apply. FORCE makes them apply to
-- the owner too, which is what catches a migration script reading across
-- tenants by accident.

ALTER TABLE "accruals" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "accruals" FORCE ROW LEVEL SECURITY;
CREATE POLICY "accruals_tenant" ON "accruals"
  USING ("organization_id" = current_setting('app.organization_id'))
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "additional_services" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "additional_services" FORCE ROW LEVEL SECURITY;
CREATE POLICY "additional_services_tenant" ON "additional_services"
  USING ("property_id" IN (SELECT "id" FROM "properties" WHERE "organization_id" = current_setting('app.organization_id')))
  WITH CHECK ("property_id" IN (SELECT "id" FROM "properties" WHERE "organization_id" = current_setting('app.organization_id')));

ALTER TABLE "app_users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "app_users" FORCE ROW LEVEL SECURITY;
CREATE POLICY "app_users_tenant" ON "app_users"
  USING ("organization_id" = current_setting('app.organization_id') OR current_setting('app.organization_id') = '')
  WITH CHECK ("organization_id" = current_setting('app.organization_id'));

ALTER TABLE "ari_sync_log" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "ari_sync_log" FORCE ROW LEVEL SECURITY;
CREATE POLICY "ari_sync_log_tenant" ON "ari_sync_log"
  USING ("connection_id" IN (SELECT "id" FROM "channel_connections" WHERE "organization_id" = current_setting('app.organization_id')))
  WITH CHECK ("connection_id" IN (SELECT "id" FROM "channel_connections" WHERE "organization_id" = current_setting('app.organization_id')));

